import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"睽","description":"東坡易傳 - 睽","frontmatter":{"title":"睽","description":"東坡易傳 - 睽"},"headers":[],"relativePath":"classics/dongpo/039.md","filePath":"classics/dongpo/039.md"}'),o={name:"classics/dongpo/039.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="睽" tabindex="-1">睽 <a class="header-anchor" href="#睽" aria-label="Permalink to “睽”">​</a></h1><p>“睽”：小事吉。</p><p>《彖》曰：“睽”，火動而上，澤動而下，二女同居，其志不同行。說而麗乎明，柔進而上行，得中而應乎剛【謂五也】。是以“小事吉”。天地“睽”而其事同也，男女“睽”而其志通也，萬物“睽”而其事類也。“睽”之時用大矣哉！</p><p>有“同”而後有“睽”。“同”而非其情，“睽”之所由生也。“說”之麗“明”，柔之應剛，可謂“同”矣，然而不可大事者，以二女之志不同也。人苟惟“同”之知，若是必“睽”。人苟知“睽”之足以有為，若是必“同”。是以自其“同”者言之，則二女同居而志不同，故其吉也小；自其“睽”而“同”者言之，則天地“睽”而其事“同”，故其用也大。</p><p>象曰：上火下澤，“睽”，君子以同而異。</p><p>“同而異”，晏平仲所謂“和”也。</p><p>初九：悔亡。喪馬，勿逐，自復。見惡人，無咎。象曰：“見惡人”，以闢咎也。</p><p>“睽”之不相應者，惟初與四也。初欲適四而四拒之，悔也。四之拒我，逸“馬”也，“惡人”也。四往無所適，無歸之馬也。馬逸而無歸，其勢自復；馬復，則“悔亡”矣。人惟好同而惡異，是以為“睽”。故美者未必婉，惡者未必狠，從我而來者未必忠，拒我而逸者未必貳。以其難致而舍之，則從我者皆吾疾也，是相率而入於咎爾。故“見惡人”，所以“闢咎”也。</p><p>九二：遇主於巷，無咎。象曰：“遇主於巷”，未失道也。</p><p>“主”，所主也。有所適，必有所主。九二之進，則主五矣。“巷”者，二五往來相從之道也。使二決從五，則見主於其室；五決從二，則見主於其門。所以相遇於巷者，皆有疑也。何疑也？疑四之為寇也。然而猶可以“無咎”者，皆未失相從之道也，特未至爾。</p><p>六三：見輿曳，其牛掣。其人天且劓，無初有終。象曰：“見輿曳”，位不當也；“無初有終”，遇剛也。</p><p>三非六之所宜據，譬之乘輿而非其人也。非其人而乘其器，無人則肆，有人則怍矣。故六三見上九，曳其輪而不進，擊其牛而去之。夫六三配上九，而近於九四，九四其寇也，無所應而噬之，未達於配而噬於寇，是以“天且劓”也。乘非其位而汙非其配，可以獲罪矣，然上九猶脫弧而納之，上九則大矣。有是大者容之，故“無初有終”。</p><p>九四：睽孤，遇元夫。交孚，厲，無咎。象曰：“交孚”“無咎”，志行也。</p><p>“睽”之世，陽惟升，陰惟降。九二升而遇五，故為遇主；九四、上九升而無所遇①，故為“睽孤”。元夫，初九也。夫兩窮而後相遇者，不約而交相信，是以雖危而“無咎”也。</p><p>【校注】 ① 九四、上九升而無所遇：《蘇氏易傳》無“上九”，誤。</p><p>六五：悔亡。厥宗噬膚，往何咎？象曰：“厥宗噬膚”，往有慶也。</p><p>六五之配，九二也；九二之“宗”，九四也。二與四同功，故亦曰“宗”。“膚”，六三也，自五言二之宗，故曰“厥宗”。六五之所以疑而不適二者，疑四之為“寇”也，故告之曰：四已噬三矣。夫既已噬三，則不暇寇我；我往從二，何咎之有？</p><p>上九：睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧。匪寇，無媾；往，遇雨則吉。象曰：“遇雨”之“吉”，無疑亡也。</p><p>上九之所見者，六三也。汙非其配，“負塗”之豕也。載非其人，“載鬼”之車也。是以張弧而待之，既而察之曰：是其所居者不得已，非與寇，為媾者也，是以說弧而納之，陰陽和而雨也。天下所以“睽”而不合者，以我求之詳也；夫苟求之詳，則孰為不可疑者？今六三之罪，猶且釋之；“群疑”之“亡”也，不亦宜哉！</p>',19)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
